// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface IndentIn {
  items: IndentLineIn[];
  note?: string | null;
}

export interface IndentLineIn {
  drug_id: number;
  qty: number | string;
  note?: string | null;
}

export interface WardIndentOut {
  indent_id: number;
  ward_id: number;
  status: "Pending" | "Approved" | "PartiallyApproved" | "Rejected" | "Cancelled";
  note: string | null;
  approval_request_id: number | null;
  requested_by: number;
  requested_at: string;
  decided_by: number | null;
  decided_at: string | null;
  row_version: number;
  ward_name: string;
  items: WardIndentItemOut[];
}

export interface WardIndentItemOut {
  ward_indent_item_id: number;
  indent_id: number;
  drug_id: number;
  qty_requested: number;
  qty_approved: number | null;
  note: string | null;
  row_version: number;
  drug_name: string;
  central_stock: number | null;
}

export interface WardStockOut {
  drug_id: number;
  drug_name: string;
  batch_id: number;
  batch_no: string;
  expiry_date: string;
  qty: number;
  updated_at: string;
  /** Expired: never given (BATCH_EXPIRED); remove it */
  is_expired: boolean;
  /** Under a recall: never given (BATCH_RECALLED); the recall removes it */
  is_recalled: boolean;
}

/** A drug with its live stock (view v_drug_stock): what e-prescription search shows. */
export interface DrugStockOut {
  drug_id: number;
  code: string;
  name: string;
  generic_name: string | null;
  strength: string | null;
  form: "Tablet" | "Capsule" | "Syrup" | "Suspension" | "Injection" | "Infusion" | "Cream" | "Ointment" | "Drops" | "Inhaler" | "Suppository" | "Powder" | "Consumable" | "Device" | "Other";
  unit: string;
  schedule: "OTC" | "ScheduleG" | "ScheduleH" | "ScheduleX" | "HospitalOnly";
  is_otc_allowed: boolean;
  barcode: string | null;
  low_stock_threshold: number;
  is_active: boolean;
  /** Set: a high-alert medicine (MSDS 56): show it in red; a second person checks it when dispensed and given */
  high_alert_category: "ConcentratedElectrolyte" | "Chemotherapy" | "Anticoagulant" | "Insulin" | "Opioid" | "Sedative" | "NeuromuscularBlocker" | "Inotrope" | "Thrombolytic" | "Psychotropic" | "HighCost" | "Other" | null;
  /** Prescribed only with the RestrictedPrescribing privilege (MSDS 52) */
  is_restricted: boolean;
  /** Medicines it looks or sounds like: warn when one is picked */
  lasa_with: string[];
  /** Non-expired stock */
  qty_available: number;
  next_expiry: string | null;
  /** OutOfStock: show the drug greyed out */
  stock_status: "InStock" | "Low" | "OutOfStock";
}

export interface WardStockRemoveIn {
  batch_id: number;
  qty: number | string;
  reason: "Expiry" | "Damage" | "ReturnToPharmacy";
  note: string;
}

export interface BedMatrixOut {
  wards: WardOccupancyOut[];
  /** Ward name -> available beds */
  summary: Record<string, number>;
  /** Only with include_beds=true */
  beds?: BedMatrixBedOut[] | null;
}

/** A ward's bed counts (view v_bed_matrix). */
export interface WardOccupancyOut {
  ward_id: number;
  code: string;
  name: string;
  ward_type: "General" | "Private" | "SemiPrivate" | "ICU" | "CCU" | "NICU" | "Surgical" | "Pediatric" | "Maternity" | "Emergency" | "Isolation" | "Other";
  gender_restriction: "male" | "female" | "any";
  total_beds: number;
  available: number;
  reserved: number;
  occupied: number;
  /** Beds being cleaned or waiting for discharge clearance */
  turnover: number;
  out_of_service: number;
}

export interface BedMatrixBedOut {
  bed_id: number;
  ward_id: number;
  label: string;
  current_state: "Available" | "Reserved" | "Occupied" | "Dirty" | "Cleaning" | "OutOfService";
  state_changed_at: string;
  is_overflow_allowed: boolean;
  admission_id: number | null;
  /** Only with with_patients=true */
  patient_name: string | null;
  /** Only with with_patients=true */
  mrn: string | null;
  admission_status: "AdmissionPending" | "Waitlisted" | "BedReserved" | "CodeRedActive" | "Admitted" | "DischargeInProgress" | "Discharged" | "Cancelled" | null;
  is_overflow: boolean | null;
  /** The discharge stage the patient in this bed waits for */
  discharge_blocked_on: string | null;
}

/** Head Nurse: ward supply requisition (indent) — POST /api/v1/wards/{ward_id}/indents (who may call: holders of ward.indent.create). */
export function createIndent(ward_id: number, body: IndentIn): Promise<WardIndentOut> {
  return api<WardIndentOut>("POST", `/wards/${ward_id}/indents`, body, { idempotent: true });
}

/** One indent with central stock per line — GET /api/v1/ward-indents/{indent_id} (who may call: holders of ward.indent.create or approval.ward_indent.approve). */
export function getIndent(indent_id: number): Promise<WardIndentOut> {
  return api<WardIndentOut>("GET", `/ward-indents/${indent_id}`, undefined);
}

/** Ward-local stock — GET /api/v1/wards/{ward_id}/inventory (who may call: holders of ward.inventory.view). */
export function wardInventory(ward_id: number): Promise<WardStockOut[]> {
  return api<WardStockOut[]>("GET", `/wards/${ward_id}/inventory`, undefined);
}

/** Formulary search with live stock colour — GET /api/v1/drugs/search (who may call: holders of pharmacy.formulary.view). */
export function searchDrugs(query?: { q?: string; limit?: number }): Promise<DrugStockOut[]> {
  return api<DrugStockOut[]>("GET", withQuery(`/drugs/search`, query), undefined);
}

/** Remove stock from a ward (expired, damaged, or returned to the pharmacy) — POST /api/v1/wards/{ward_id}/inventory/remove (who may call: holders of ward.indent.create or pharmacy.stock.adjust). */
export function removeWardStock(ward_id: number, body: WardStockRemoveIn): Promise<WardStockOut[]> {
  return api<WardStockOut[]>("POST", `/wards/${ward_id}/inventory/remove`, body, { idempotent: true });
}

/** Live bed matrix (counts per ward + optional bed list) — GET /api/v1/beds/matrix (who may call: holders of ipd.bed.view or cssd.operate or infection.control.manage or complaint.manage or incident.view or facility.drill.manage or roster.manage.all or facility.equipment.manage or pharmacy.storage.record). */
export function bedMatrix(query?: { include_beds?: boolean }): Promise<BedMatrixOut> {
  return api<BedMatrixOut>("GET", withQuery(`/beds/matrix`, query), undefined);
}
